theme.css:
/* theme: Circuit Breakers | A red-alert tech rout crashes the market page, while defensive rotations and security failures pull everything into a stark, high-voltage palette. */
/* layout: hero=centered; political-news=numbered/masonry; financial-news=stat/grid-2; entertainment-news=tile/stack; music-releases=lede/grid-3; stock-analysis=stat/feature; outlook=outline/rail */

.diary-page {
  --paper: #0e0b0d;
  --paper-alt: #191417;
  --ink: #f5f1f0;
  --ink-soft: #d4ccca;
  --muted: #a79d9a;
  --accent: #ff3b30;
  --accent-ink: #1a0d0c;
  --rule: #3a3030;
  --font-display: var(--ff-syne), sans-serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-space-grotesk), system-ui, sans-serif;
}

.diary-page[data-hero="centered"] .diary-hero {
  background: var(--paper);
  border-bottom: 2px solid var(--accent);
}

.diary-page[data-hero="centered"] .diary-hero-inner {
  padding-block: 3rem 4rem;
  text-align: center;
}

.diary-page[data-hero="centered"] .diary-kicker {
  margin-top: 0;
  letter-spacing: 0.3em;
  font-weight: 700;
}

.diary-page[data-hero="centered"] .diary-title {
  margin-inline: auto;
  font-family: var(--font-display);
  font-size: clamp(3rem, 8vw, 6rem);
  font-weight: 800;
  letter-spacing: -0.04em;
  line-height: 0.9;
  max-width: 13ch;
  text-transform: uppercase;
  color: var(--ink);
}

.diary-page[data-hero="centered"] .diary-summary,
.diary-page[data-hero="centered"] .diary-theme-note {
  margin-inline: auto;
}

.diary-page[data-hero="centered"] .diary-summary {
  margin-top: 2rem;
  max-width: 34rem;
  font-size: clamp(1.05rem, 2vw, 1.3rem);
  line-height: 1.6;
  color: var(--ink-soft);
}

.diary-page[data-hero="centered"] .diary-theme-note {
  margin-top: 1.5rem;
  max-width: 30rem;
  font-family: var(--font-ui);
  font-size: 0.85rem;
  color: var(--muted);
}

.diary-page[data-hero="centered"] .diary-theme-name {
  background: var(--accent);
  color: var(--accent-ink);
  border-radius: 0;
  padding: 0.15rem 0.8rem;
  font-weight: 700;
  letter-spacing: 0.05em;
}

.diary-page .diary-crumbs a {
  color: var(--muted);
}

.diary-page .diary-crumbs a:hover {
  color: var(--accent);
}

.diary-page .diary-toc {
  background: var(--paper);
  border-bottom: 1px solid var(--rule);
}

.diary-page .diary-toc-link {
  color: var(--muted);
}

.diary-page .diary-toc-link:hover,
.diary-page .diary-toc-link.is-active {
  color: var(--ink);
}

.diary-page .diary-toc-number {
  color: var(--accent);
  font-weight: 700;
}

.diary-page .diary-section {
  border-top: 2px solid var(--rule);
  padding-block: 3.5rem;
}

.diary-page .diary-section-head {
  margin-bottom: 2rem;
}

.diary-page .diary-section-number {
  color: var(--accent);
  font-weight: 700;
  font-family: var(--font-ui);
  letter-spacing: 0.15em;
}

.diary-page .diary-section-title {
  font-family: var(--font-display);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  text-transform: uppercase;
  color: var(--ink);
}

/* Cards */
.diary-page .diary-card--numbered .diary-card-index {
  font-family: var(--font-display);
  font-size: 2.8rem;
  color: var(--accent);
  font-weight: 700;
  line-height: 0.8;
  letter-spacing: -0.03em;
}

.diary-page .diary-card--numbered .diary-card-inner {
  gap: 0.4rem;
}

.diary-page .diary-card--numbered .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.3rem;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--ink);
}

.diary-page .diary-card--numbered .diary-card-body {
  font-size: 1rem;
  line-height: 1.65;
  color: var(--ink-soft);
}

.diary-page .diary-card--numbered .diary-card-thread {
  margin-top: 0.5rem;
  background: transparent;
  border: 1px solid var(--accent);
  color: var(--accent);
  font-family: var(--font-ui);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.03em;
  border-radius: 999px;
}

.diary-page .diary-card--numbered .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

.diary-page .diary-card--stat .diary-card-inner {
  padding-top: 1.25rem;
  border-top: 4px solid var(--accent);
}

.diary-page .diary-card--stat .diary-card-figure {
  font-family: var(--font-display);
  font-size: clamp(2.5rem, 14cqi, 4.5rem);
  font-weight: 800;
  letter-spacing: -0.04em;
  color: var(--accent);
}

.diary-page .diary-card--stat .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.2rem;
  font-weight: 600;
  color: var(--ink);
}

.diary-page .diary-card--stat .diary-card-body {
  font-size: 1rem;
  line-height: 1.6;
  color: var(--ink-soft);
}

.diary-page .diary-card--lede .diary-card-lede {
  padding-left: 1.25rem;
  border-left: 4px solid var(--accent);
  font-family: var(--font-display);
  font-size: 1.35rem;
  line-height: 1.4;
  color: var(--ink);
}

.diary-page .diary-card--lede .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 600;
  color: var(--ink);
}

.diary-page .diary-card--lede .diary-card-body {
  font-size: 1rem;
  line-height: 1.65;
  color: var(--ink-soft);
}

.diary-page .diary-card--outline .diary-card-inner {
  padding: 1.5rem;
  border: 1px solid var(--rule);
  background: var(--paper-alt);
}

.diary-page .diary-card--outline .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.15rem;
  font-weight: 600;
  color: var(--ink);
}

.diary-page .diary-card--outline .diary-card-body {
  font-size: 1rem;
  line-height: 1.6;
  color: var(--ink-soft);
}

.diary-page .diary-card--tile .diary-card-inner {
  padding: 1.5rem;
  background: var(--paper-alt);
  border-bottom: 3px solid var(--accent);
}

.diary-page .diary-card--tile .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.3rem;
  font-weight: 600;
  color: var(--ink);
}

.diary-page .diary-card--tile .diary-card-body {
  font-size: 1rem;
  line-height: 1.65;
  color: var(--ink-soft);
}

/* Prose refinements */
.diary-page .diary-prose {
  font-size: 1.08rem;
  line-height: 1.7;
  color: var(--ink-soft);
}

.diary-page .diary-prose a {
  color: var(--accent);
  border-bottom: 1px solid currentColor;
}

.diary-page .diary-prose a:hover {
  color: var(--ink);
}

.diary-page .diary-prose strong {
  color: var(--ink);
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
  width: 0.5rem;
  height: 3px;
}

.diary-page .diary-prose ol > li::marker {
  color: var(--accent);
}

.diary-page .diary-prose blockquote {
  border-left: 4px solid var(--accent);
  color: var(--ink);
}

/* Section-specific adjustments */
.diary-page [data-section="financial-news"] .diary-card--stat .diary-card-figure {
  color: var(--accent);
}

.diary-page [data-section="stock-analysis"] .diary-card--stat .diary-card-figure {
  font-size: clamp(3rem, 18cqi, 6rem);
  margin-bottom: 0.25rem;
}

/* Layout-specific: rail for outlook */
.diary-page .diary-stories--rail {
  grid-auto-columns: minmax(16rem, 80%);
}

.diary-page .diary-stories--rail > .diary-card {
  scroll-snap-align: start;
}

/* Market sparklines: maintain contrast on dark paper */
.diary-page .diary-spark {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
}

.diary-page .diary-spark-label {
  color: var(--muted);
}

.diary-page .diary-spark-value {
  color: var(--ink);
}

.diary-page .diary-spark.is-up .diary-spark-change {
  color: #4cd964;
}

.diary-page .diary-spark.is-down .diary-spark-change {
  color: var(--accent);
}

.diary-page .diary-spark-line polyline {
  stroke: var(--ink-soft);
}

.diary-page .diary-markets-label {
  color: var(--muted);
}

/* Footer */
.diary-page .diary-footer {
  border-top: 2px solid var(--rule);
  color: var(--muted);
}

.diary-page .diary-footer a {
  color: var(--ink);
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}

/* Desktop sidebar */
@media (min-width: 1024px) {
  .diary-page .diary-toc {
    border-left: 1px solid var(--rule);
  }

  .diary-page .diary-toc-link {
    border-left: 2px solid transparent;
  }

  .diary-page .diary-toc-link.is-active {
    border-left-color: var(--accent);
  }
}
